update public.questions set statement='Suponha que, em 1994, um artigo custasse R$ 13,91 e, exatos 28 anos depois (336 meses), ele passasse a custar R$ 100,00. Suponha, também, que, para esse período, a taxa mensal de aumento no preço desse artigo tenha sido igual a k%, ou seja, a cada mês o preço do artigo sofreu um aumento de k% em relação ao preço do mês anterior. O valor de k pode ser dado por', image_url='/questions/2023/q12.png' where exam_id=(select id from public.exams where slug='transpetro-2023-dutos-e-terminais') and question_number=12;
update public.questions set statement='Uma empresa, em reconhecimento ao desempenho de 10 de seus funcionários, decide dar-lhes um bônus. Para tanto, a empresa distribuiu um total de R$ 25.000,00: 6 funcionários receberam R$ 2.000, 2 receberam R$ 2.500 e 2 receberam R$ 4.000. Nessas condições, o desvio padrão dos bônus pagos é dado por', image_url='/questions/2023/q13.png' where exam_id=(select id from public.exams where slug='transpetro-2023-dutos-e-terminais') and question_number=13;
update public.questions set statement='O PTFE é um fluoropolímero sintético com alta massa molecular, cujo precursor monomérico é o tetrafluoretileno (TFE). O PTFE é conhecido por ser antiaderente, ter alta estabilidade térmica e baixa reatividade química. Das estruturas a seguir, a que representa a unidade de repetição do PTFE é a', image_url='/questions/2023/q25.png' where exam_id=(select id from public.exams where slug='transpetro-2023-dutos-e-terminais') and question_number=25;
update public.questions set statement='Considere um sistema de equações que envolvem reações de hidrocarbonetos As substâncias X, Y e Z são, respectivamente', image_url='/questions/2023/q27.png' where exam_id=(select id from public.exams where slug='transpetro-2023-dutos-e-terminais') and question_number=27;
update public.questions set statement='Uma viga de seção transversal retangular de dimensões b × h é submetida a um momento fletor M, conforme indicado na Figura. A tensão normal compressiva máxima na seção mostrada atuará no(s) ponto(s)', image_url='/questions/2023/q29.png' where exam_id=(select id from public.exams where slug='transpetro-2023-dutos-e-terminais') and question_number=29;
update public.questions set statement='O descarregamento de uma caixa de massa m é realizado com o deslizamento da caixa por um plano inclinado de α graus (10° < α < 30°), conforme mostrado na Figura, com atrito nulo entre a caixa e o plano. Sendo g a aceleração da gravidade, a aceleração de deslizamento da caixa sobre o plano', image_url='/questions/2023/q30.png' where exam_id=(select id from public.exams where slug='transpetro-2023-dutos-e-terminais') and question_number=30;
update public.questions set statement='Na Figura, representa-se uma força concentrada F, aplicada à extremidade da viga biapoiada ABCD, com o objetivo de elevar uma carga posicionada conforme indicado. O menor valor da força F, expressa em newtons, para elevar uma carga P de 2.100 N, que faz com que a reação no apoio A seja nula, é', image_url='/questions/2023/q31.png' where exam_id=(select id from public.exams where slug='transpetro-2023-dutos-e-terminais') and question_number=31;
update public.questions set statement='A estrutura representada na Figura é constituída de 3 barras unidas pelo pino B. Considere que as barras 1 e 2 tenham área de seção transversal de 1,0 cm², e a barra 3, área de 1,2 cm². As tensões normais que atuam nas barras 1, 2 e 3 para suportar a carga P de 2.400 N são, em MPa, respectivamente, de', image_url='/questions/2023/q32.png' where exam_id=(select id from public.exams where slug='transpetro-2023-dutos-e-terminais') and question_number=32;
update public.questions set statement='Considere uma força magnética atuando em um condutor retilíneo de comprimento l, percorrido por uma corrente i. Esse condutor está imerso em uma região onde existe um campo magnético uniforme (B), que forma um ângulo θ com o condutor. Essa força magnética é representada pela seguinte equação:', image_url='/questions/2023/q35.png' where exam_id=(select id from public.exams where slug='transpetro-2023-dutos-e-terminais') and question_number=35;
update public.questions set statement='O dispositivo representado na Figura é um tubo de Venturi, que compreende duas seções, a maior com área S1, e a menor, com área S2, ambas conhecidas. Nas direções verticais correspondentes aos pontos P1 e P2, são conectados dois tubos verticais, ambos com as extremidades superiores abertas e as inferiores em comunicação com o interior desse tubo, por onde um fluido conhecido é canalizado. Considere que v1 é a velocidade na região S1; v2, a velocidade na região S2 (garganta); e Δh, a medida do desnível do líquido existente nos tubos verticais. Esse dispositivo é usado para medir', image_url='/questions/2023/q39.png' where exam_id=(select id from public.exams where slug='transpetro-2023-dutos-e-terminais') and question_number=39;
update public.questions set statement='O recipiente cilíndrico de diâmetro igual a 12 m, representado na Figura, é aberto no topo e contém água, cuja densidade é igual a 1.000 kg/m³, até a linha indicada. O nível da água no interior do reservatório está a uma altura h1 = 10,8 m, e a tubulação de saída, um duto circular com 20 cm² de área de seção reta, está a uma altura h2 = 9 m. Considerando-se a situação apresentada, a vazão de saída de água, em kg/s, é igual a (Dado: g = 10 m/s²)', image_url='/questions/2023/q40.png' where exam_id=(select id from public.exams where slug='transpetro-2023-dutos-e-terminais') and question_number=40;
update public.questions set statement='Na Figura, são mostrados 3 vasos, A, B e C, abertos para a atmosfera. Esses vasos têm formas diferentes, mas foram preenchidos com água até o mesmo nível. A relação entre as pressões no fundo de cada um deles é descrita por', image_url='/questions/2023/q56.png' where exam_id=(select id from public.exams where slug='transpetro-2023-dutos-e-terminais') and question_number=56;